const { writeFileSync } = await import('node:fs');
if (!globalThis.input || typeof globalThis.input.html !== 'string' || typeof globalThis.input.output_path !== 'string') {
  throw new Error('Required inputs "html" and "output_path" are missing or not strings');
}
const htmlPath = '/tmp/input.html';
writeFileSync(htmlPath, globalThis.input.html);
globalThis.htmlPath = htmlPath;
globalThis.pdfPath = globalThis.input.output_path;

const mod = await import('topdf');
const topdf = mod.default || mod;
if (typeof topdf === 'function') {
  // Assume signature (htmlPath, pdfPath) returns a Promise or uses callback
  const result = topdf(globalThis.htmlPath, globalThis.pdfPath);
  if (result && typeof result.then === 'function') await result;
} else if (typeof topdf.convert === 'function') {
  const result = topdf.convert(globalThis.htmlPath, globalThis.pdfPath);
  if (result && typeof result.then === 'function') await result;
} else {
  throw new Error('Unsupported topdf API: no callable function found');
}

if (!globalThis.pdfPath) {
  throw new Error('PDF path not set');
}
